C = dict(id='GL-21', title='E-Commerce Growth Marketing', group='Business and Commerce', level=4,
 summary='Grow an online shop with honest, measured marketing: find the right buyers, test offers and messages, and track cost per sale until it pays.',
 outcomes=['Explain the funnel from visit to repeat purchase and the numbers that describe it.', 'Run small tests of messages, offers and pages.', 'Analyse cost per sale, margin and return on spend.', 'Create a 30-day growth plan with budget and measures.', 'Evaluate which actions to keep, change or stop.'],
 task='Run a 30-day growth plan for one real or practice online shop, reaching a target cost per sale below the margin.',
 cond='A shop or product page, small test budget (own currency), analytics, a spreadsheet, a mentor with sales experience and a peer circle. About 10 weeks part-time.',
 std='Funnel numbers recorded weekly; at least three tests with a clear winner or lesson; cost per sale lower than gross margin per sale; consent kept for all emails; honest claims only.',
 who='Shop owners, marketers, sales staff, freelancers, students.', req='Access to a shop or practice product page.',
 safety='Keep claims true. Follow advertising and consumer rules, and ask for consent before email or message marketing. Do not use fake reviews.',
 mods=[
 ('The funnel', 'Sales follow steps; each step loses people.', ['Visit, view product, add to cart, check out, pay, return.', 'Conversion rate at each step.', 'Find the biggest leak first.', 'Repeat customers cost less to win.'], '1,000 visits, 60 carts, 20 orders: visit-to-order 2%; cart-to-order 33%.', 'Draw your funnel with numbers.', 'Rates computed for each step.'),
 ('Know the buyer', 'A message works when it fits a real person.', ['Describe one buyer: need, worry, budget, where they look.', 'Talk to five buyers or read their reviews.', 'Write the main benefit in a sentence.', 'Choose one channel to start.'], 'Buyer: parent buying school bags; worry: weight and strength; benefit: "Light bag that lasts two school years."', 'Interview five buyers and write the profile.', 'Profile uses their words.'),
 ('Product page and offer', 'The page must answer questions fast.', ['Clear title, photos, price, delivery, returns.', 'Honest reviews.', 'One main button.', 'Offer: bundle, free delivery over a threshold, small discount.'], 'Free delivery over 40 raises average basket from 32 to 38 (an estimate; check your market).', 'Improve one page and list changes.', 'Changes tied to buyer worries.'),
 ('Channels and budget', 'Small budgets need focus.', ['Search, social, email, partners, marketplaces.', 'Start with one or two channels.', 'Set daily budget and stop rule.', 'Track with simple links.'], 'Budget 150 for 30 days; stop an ad if 20 clicks bring no sale.', 'Write the channel plan with budget.', 'Budget and stop rule written.'),
 ('Test one thing at a time', 'A test needs two versions and a number.', ['Pick one change: headline, image, price, offer.', 'Run both at the same time to similar people.', 'Wait for enough results.', 'Record winner and lesson.'], 'Headline A gets 3 sales from 150 clicks (2%); headline B gets 7 (4.7%): choose B.', 'Run three tests.', 'Each test has data and a decision.'),
 ('Email and repeat sales', 'Existing customers are the cheapest sales.', ['Ask for consent; offer an easy opt-out.', 'Welcome mail, order mail, reminder mail.', 'Useful content over constant offers.', 'Measure opens, clicks, sales.'], 'A reminder to buyers after 30 days brings 6 reorders from 100 mails (6%).', 'Write a three-mail sequence.', 'Consent shown; unsubscribe included.'),
 ('Numbers that matter', 'Know what each sale costs.', ['Cost per sale = spend / sales.', 'Margin per sale = price - product cost - delivery - fees.', 'Return on spend = revenue / spend.', 'Keep margin above cost per sale.'], 'Spend 150, 25 sales: 6.00 each. Margin 11.00 per sale, so profit 5.00 per sale.', 'Build a numbers table for the month.', 'Formulas correct; currency shown.'),
 ('Review and scale', 'Do more of what works.', ['Keep winners, stop losers.', 'Raise budgets slowly.', 'Share lessons in the peer circle.', 'Plan 90 days.'], 'Social ad cost per sale 12.50 above margin: stop. Search ad 4.10: raise by 20%.', 'Write the review and next plan.', 'Decisions use numbers.')],
 quiz=[('What is conversion rate?', 'Orders divided by visits (or step to step), as a percentage.'), ('Cost per sale formula?', 'Spend divided by sales.'), ('Why test one thing?', 'Otherwise you cannot tell what caused the change.'), ('What is margin per sale?', 'Price minus product cost, delivery and fees.'), ('Why get consent for email?', 'It is the law in most places and builds trust.'), ('What is a stop rule?', 'A limit that ends a test that is not working.'), ('Why start with one channel?', 'Focus gives clearer learning on a small budget.'), ('What is a funnel leak?', 'A step where many people drop out.'), ('Why avoid fake reviews?', 'They are dishonest and often illegal.'), ('When do you scale?', 'When cost per sale is below margin and holds steady.')],
 rubric=[('Buyer insight', 'Five buyers heard', 'Words reused in copy and tested'), ('Tests', 'Three tests with decisions', 'Tests changed results'), ('Numbers', 'Cost per sale and margin correct', 'Weekly trend explained'), ('Compliance', 'Consent and honest claims', 'Reviewed by adviser'), ('Review', 'Keep, change, stop list', 'Scaled winner with new results')],
 jobs=[('E-commerce marketing assistant', 'Runs tests and reports'), ('Shop growth coordinator', 'Plans offers and emails'), ('Performance marketing trainee', 'Manages small ad budgets'), ('Freelance growth consultant', 'Helps small shops')],
 next='Marketplace Fulfilment Selling; Digital Marketing; E-Commerce Inventory Management.',
 local='Advertising, consent and consumer-return rules differ by place; check the local rule before running offers.',
 evidence='Your evidence: funnel table, buyer profile, page changes, channel plan, three test records, email sequence, numbers table and review.',
 ladder=[('Basics of selling online', 'Describe a sale step by step, from seeing a product to receiving it. Notes: buy something small online and write down each step you took. Standard: a list of at least six steps in order.'), ('Awareness', 'Describe the funnel (see, click, add, pay) and name the channels shops use. Notes: trace one advert you see to the shop page and count the steps. Standard: each step has a number or a guess marked as a guess.'), ('Foundation', 'Calculate margin and a break-even cost per sale for one product, and write a test idea for one advert. Notes: practice figures from a worksheet, with currency. Standard: the break-even cost per sale is correct and the test has a stop rule.'), ('Practitioner', 'Run two small adverts or emails, record clicks and sales, and decide which to keep. Notes: practice budget only. Standard: decision backed by counts, with the date and cost recorded.'), ('Specialist', 'Run a 30-day growth plan for one real or practice online shop, reaching a target cost per sale below the margin. Notes: weekly review with a stop rule. Standard: cost per sale under margin by week four, with records.'), ('Advanced', "Manage several shops' growth with a testing calendar, shared reports and a channel budget. Notes: add a cohort view of repeat buyers. Standard: budget moves toward channels with lower cost per sale, with the reason written."), ('Super expert', 'Set the experiment method for e-commerce growth (hypothesis, test, stop rule) and teach the marketers who use it. Notes: review test records yearly and retire any result that no longer holds.')])

C['deep'] = dict(mods=[
 ('Looking at total visits only.', 'Visits rise but orders do not: the leak is at checkout.', 'Where is your biggest leak?'),
 ('Writing for yourself, not the buyer.', 'Switch from "premium bag" to "light bag that lasts two years".', 'Which words came from buyers?'),
 ('Too many choices on the page.', 'One main button lifts clicks.', 'What is your one button?'),
 ('Spreading a small budget thin.', '150 on one channel teaches more than 30 on five.', 'Which channels did you choose?'),
 ('Changing two things at once.', 'Headline and image changed together hide the cause.', 'What single change did you test?'),
 ('Emailing without consent.', 'Opt-in only; one-click unsubscribe.', 'Where is consent recorded?'),
 ('Counting revenue instead of margin.', '25 sales of 20.00 sound good, but margin is 11.00 and ad cost 6.00.', 'What is your profit per sale?'),
 ('Scaling too fast.', 'Raise spend 20% a week while cost holds.', 'What is your scale rule?')],
 gloss=[('Funnel', 'Steps from visit to purchase.'), ('Conversion rate', 'Share who take the next step.'), ('Margin', 'Money left after costs.'), ('A/B test', 'Comparing two versions.'), ('Opt-in', 'Permission given by the person.'), ('Return on spend', 'Revenue divided by spend.')],
 cases=[('The expensive click', 'Cost per sale 9.50, margin 8.00.', 'What do you do?', 'Stop or fix the ad and page; do not scale.'),
        ('The cart leak', '60 carts, 20 orders.', 'What do you check?', 'Shipping cost shock, payment options, forced sign-up; test one change.')])
