_ex = ['1,000 visits, 60 carts, 20 orders: visit-to-order 2%; cart-to-order 33%. The biggest leak is visit to cart.', "Buyer: parent buying school bags; worry: weight and strength; benefit: 'Light bag that lasts two school years.'", 'Free delivery over 40 raises the average basket from 32 to 38 across 100 orders.', 'Budget 150 for 30 days; an ad stops if 20 clicks bring no sale.', 'Headline A gets 3 sales from 150 clicks (2%); headline B gets 7 (4.7%). Choose B and record why.', 'A reminder to buyers after 30 days brings 6 reorders from 100 mails (6%).', 'Spend 150, 25 sales: 6.00 each. Margin 11.00 per sale, so profit 5.00 per sale.', 'Social ad cost per sale 12.50 is above margin: stop. Search ad 4.10: raise by 20%.']
_extra = ["Draw the buyer's journey in five steps.", 'Collect five real buyer questions and answer them on the page.', 'Check page speed on a phone.', 'Compare your price with three similar sellers.', 'Put returns and delivery details near the button.', 'Use one clear photo that shows size.', 'Test one email subject line against another.', 'Keep a record of every test and result.', 'Ask buyers why they chose you.', 'Include a way to opt out in every message.', 'Check ad claims are true and provable.', 'Set a weekly spending limit and stick to it.', 'Record the margin before any discount.', 'Use the winners again in new ads.', 'Stop ideas that fail twice.', "Write next month's plan with three tests."]
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Map your funnel with real counts: 1,000 visitors, 40 add to basket, 20 start checkout, 12 buy; the biggest drop shows where to work first, here the step from visit to basket.', 'Calculate your conversion rate by dividing orders by visitors; 12 orders from 1,000 visitors is 1.2 percent, and a small lift to 1.5 percent is a 25 percent rise in orders.'], ['Write a buyer profile with age range, need, where they spend time online, what worries them about buying, and three words they use to describe the product.', 'Talk to five past buyers for ten minutes each and note the exact phrases they use; reuse those phrases in your titles and descriptions.'], ['Place the main photo, price, delivery time and a clear buy button at the top of the page without scrolling, and add at least four photos including one showing size beside a common object.', 'Write the first line of the description as the benefit in under 15 words, then list three facts, then add delivery and returns details to reduce doubt.'], ['Start with a monthly budget you can afford to lose, such as 100 units, split between two channels, and compare cost per order after two weeks before adding more.', 'Work out your maximum cost per order: if profit before ads is 8 units, you cannot pay more than 8 to win an order, and should aim well below that.'], ["Write each test as a sentence: 'If we change X, then Y will rise by Z within two weeks'; pick one change, such as the headline, and leave everything else unchanged.", 'Wait for at least 100 visitors or 2 weeks per version before judging, and record the result in a log with date, change, numbers and what you will do next.'], ['Send a welcome email thanking the subscriber, with your best-selling product linked, within an hour of signing up, and a follow-up three days after a purchase asking how the product is working.', 'Plan a simple sequence of three emails over 14 days, with one clear action each, and measure the open rate and orders per email to see which one deserves more effort.'], ['Review five numbers every week: visitors, conversion rate, average order value, cost per order and repeat purchase rate, written on one page with last week beside this week.', 'Know your break-even: if monthly costs are 600 and profit per order is 10, you need 60 orders to cover them, and everything above that is gain.'], ['Scale only what works: if a channel returns twice its cost over a month, raise its budget by about 20 percent and watch for a fall in return before raising again.', 'Write a monthly plan with three tests, one owner, one date and one measure each, then review at month end and keep a list of what you learned.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {1: "A shop's weekly funnel: 800 visits, 120 product views, 36 carts, 12 orders. Visit-to-order is 1.5% and views-to-cart is 30%; the biggest drop is visit to product view, so fix the first page.", 2: "Buyer: a young cook setting up a first kitchen; worry: spending on gear that breaks; benefit: 'Five tools that cost under 40 together and last years.'", 3: 'A bundle of three notebooks for 9.00 instead of 4.00 each raises the average order from 6.00 to 8.50 in the first 60 orders.', 4: 'Budget 200 over 4 weeks: 120 search, 50 social, 30 email tools. Review each Friday and move money to the channel with the lowest cost per sale.', 5: 'Photo A (product alone) gets 2 sales from 200 views (1%); photo B (product in use) gets 6 (3%). Keep B, test the price next.', 6: 'A welcome series of 3 emails over 7 days brings 9 first orders from 150 new subscribers (6%); the third mail has the highest unsubscribes, so it is shortened.', 7: 'Spend 300, 40 sales: 7.50 each. Margin 12.00 per sale, so profit 4.50 per sale and 180 in total, before time costs.', 8: 'After 8 weeks: search sales cost 3.80, social 13.00, email 1.10. Margin is 12.00, so stop social, add 25% to search and write one more email.'}
C['deep']['mods'] = [(m[0], _dupfix.get(i + 1, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]

_dupfix2 = {7: "One month: ads cost 300 and bring 40 sales, so each sale costs 7.50. Each sale earns 12.00 margin, leaving 4.50, so 40 sales earn 180 before the owner's time."}
C['deep']['mods'] = [(m[0], _dupfix2.get(i + 1, m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ['You will map a funnel using real counts and find the single step where most shoppers leave, so effort goes where it pays back.', "You will build a buyer profile from five short conversations and borrow customers' own phrases, making your messages sound like them.", 'You will arrange a product page so price, photos, delivery and buy button answer doubts quickly, and write benefit-first descriptions.', 'You will split a small budget across two channels and calculate your maximum cost per order, so advertising never loses money silently.', 'You will state a test as an if-then sentence, change one thing, and log the result, learning from evidence instead of opinion.', 'You will set up a welcome email and a short follow-up sequence, turning first-time buyers into repeat customers at low cost.', 'You will track five weekly numbers and calculate break-even orders, knowing exactly how many sales are needed to cover your costs.', 'You will decide when a channel earns more budget and write a monthly plan with owners and measures, scaling only what is proven.']
